  "examples" = { {
      "note" = "the lava dice spans: 2d6 days fluid, 2d4 days thick, 2d3 weeks of heat retention, 2d6 points of pyroclastic hit damage",
      "expr" = "m['whzFluidLavaDaysMin']() + 10 != m['whzFluidLavaDaysMax']() or m['whzThickLavaDaysMin']() + 6 != m['whzThickLavaDaysMax']() or m['whzLavaHeatWeeksMin']() + 4 != m['whzLavaHeatWeeksMax']() or m['whzPyroclasticDmgMin']() + 10 != m['whzPyroclasticDmgMax']()",
    }, {
      "note" = "the 50-degree fluid and 30-degree thick temperature rises are exact multiples of the 10-degree-per-quarter-mile taper",
      "expr" = "m['whzFluidTempRiseDeg']() != m['whzLavaTempTaperDeg']() * 5 or m['whzThickTempRiseDeg']() != m['whzLavaTempTaperDeg']() * 3",
    }, {
      "note" = "the fluid band's 1.5-mile no-heat distance is the thick band's 1 mile plus two more quarter-mile tapers",
      "expr" = "m['whzFluidNoHeatQmi']() != m['whzThickNoHeatQmi']() + 2",
    }, {
      "note" = "the danger radii strictly ascend with intensity: 500 yards of lava heat, 2,000 light ash, 4,000 heavy ash",
      "expr" = "m['whzAshHeavyDangerYards']() <= m['whzAshLightDangerYards']() or m['whzAshLightDangerYards']() <= m['whzLavaHeatRangeYards']()",
    }, {
      "note" = "the light-band dice: 1d4+2 weeks, 1d10+15 downwind miles, 1d6+4 near miles, and the 3-8-day pyroclastic spell of band 6",
      "expr" = "m['whzAshLightWeeksMin']() + 3 != m['whzAshLightWeeksMax']() or m['whzAshLightFarMilesMin']() + 9 != m['whzAshLightFarMilesMax']() or m['whzAshLightNearMilesMin']() + 5 != m['whzAshLightNearMilesMax']() or m['whzAshSixPyrDaysMin']() + 5 != m['whzAshSixPyrDaysMax']()",
    }, {
      "note" = "the heavy-band dice: 1d6+5 daily hours, 1d3 weeks, 1d6+9 downwind miles, 1d6+2 near miles",
      "expr" = "m['whzAshHeavyHoursMin']() + 5 != m['whzAshHeavyHoursMax']() or m['whzAshHeavyWeeksMin']() + 2 != m['whzAshHeavyWeeksMax']() or m['whzAshHeavyFarMilesMin']() + 5 != m['whzAshHeavyFarMilesMax']() or m['whzAshHeavyNearMilesMin']() + 5 != m['whzAshHeavyNearMilesMax']()",
    }, {
