  "bools" = { {
      "name" = "wfcWildernessPositions",
      "value" = true,
      "comment" = "characters prefer to engage in the best position for attack and defense, but the wilderness and its creatures are not usually accommodating - characters will often have to attack or defend in far-from-best positions, sometimes enjoying the advantage when the tables are turned",
    }, {
      "name" = "wfcOutdoorNonstandardDetail",
      "value" = true,
      "comment" = "some of the DSG rules are summarized here for those without the volume, and the section goes into detail about other nonstandard combat situations peculiar to the outdoors",
    }, {
      "name" = "wfcClimberNoDexBonus",
      "value" = true,
      "comment" = "a character negotiating a severe slope or a cliff face who must attack or defend does not benefit from any armor class bonus due to dexterity, because his attention and effort are at least partially focused on climbing",
    }, {
      "name" = "wfcClimberLowDexPenaltyStays",
      "value" = true,
      "comment" = "an armor class penalty for low dexterity is not negated while climbing",
    }, {
      "name" = "wfcOneHandToClimb",
      "value" = true,
      "comment" = "assuming the climber needs one hand to hold onto a rope or the surface, he cannot use two weapons, or a weapon and a shield, at the same time",
    }, {
      "name" = "wfcRearAttackVulnerable",
      "value" = true,
      "comment" = "since he is facing the surface he is climbing, the climber is vulnerable to attacks from behind - with all appropriate penalties - from any opponent except one that is adjacent to him on the surface",
    }, {
      "name" = "wfcElevNeedsHalfHeight",
      "value" = true,
      "comment" = "if opponents engage from different elevations on a cliff face - one combatant above the other by at least half of the higher combatant's height - the elevation adjustments apply",
    }, {
      "name" = "wfcElevAdjustmentsCumulative",
      "value" = true,
      "comment" = "the elevation adjustments are cumulative with any other modifiers that may apply",
    }, {
      "name" = "wfcDamageClimbingCheck",
      "value" = true,
      "comment" = "if a character climbing a cliff face suffers damage from an attack in missile or melee combat - including damage from a spell effect - he must make a Climbing Check immediately: success and he remains in place, failure and he falls",
    }, {
      "name" = "wfcBigDamageHalfHpCheck",
      "value" = true,
      "comment" = "if a character takes damage from a single attack equal to or greater than one-half of his total hit points, rounded up, a Climbing Check to avoid falling must be made",
    }, {
      "name" = "wfcModerateSlopeNoDisadvantage",
      "value" = true,
      "comment" = "climbing a gentle or even a moderate slope does not usually put a character at a disadvantage in combat - such terrain is usually not so steep that the climber cannot stand up with the full use of both hands and reasonable mobility",
    }, {
      "name" = "wfcModerateElevOption",
      "value" = true,
      "comment" = "at the Dungeon Master's discretion, the to-hit adjustments for relative elevation (+1 and -1) may apply on a moderate slope, especially one just short of qualifying for the severe category",
    }, {
      "name" = "wfcModerateDamageTumbleOption",
      "value" = true,
      "comment" = "the Dungeon Master may rule that a character on a moderate or gentle slope who takes a significant amount of damage in a single attack will be knocked off his feet and tumble down the slope",
    }, {
      "name" = "wfcVoluntaryTumbleEscape",
      "value" = true,
      "comment" = "if a character is extremely outmanned and prefers not to stand and fight, voluntarily tumbling down a slope to get away from his enemies might be a viable strategy",
    }, {
      "name" = "wfcBalancedDefinition",
      "value" = true,
      "comment" = "a precariously balanced character is perched on a surface where he does not need to use at least one hand to hold on, and does not necessarily have to face the surface his body is next to",
    }, {
      "name" = "wfcBalancedExamples",
      "value" = true,
      "comment" = "a character is precariously balanced when standing on a ledge jutting from a cliff face or severe slope; on a narrow bridge of rock or a fallen tree spanning a canyon; standing up in a boat or on the edge of a barge; standing in knee-deep water or mud, or upon loose soil or snow in which the feet sink beneath the surface; and standing upon a level but slippery surface",
    }, {
      "name" = "wfcMissDexCheck",
      "value" = true,
      "comment" = "whenever a character engaged in melee combat misses an attack, he must make a successful Dexterity Check to avoid losing his balance and falling down - perhaps falling a long distance",
    }, {
      "name" = "wfcSlipperyNoDexMod",
      "value" = true,
      "comment" = "no modifier for a character standing on a slippery surface, where his ability to keep his balance depends entirely on how dextrous he is and not on some advantage of his location",
    }, {
      "name" = "wfcBigHitDexCheck",
      "value" = true,
      "comment" = "if a character in a precarious position at a high elevation is hit by an attack that causes loss of consciousness or inflicts damage equal to or greater than a threshold fraction of his total hit points, he must make a successful Dexterity Check to avoid falling from his position",
    }, {
      "name" = "wfcStaggerBeforeFall",
      "value" = true,
      "comment" = "a character who falls despite being a fair distance from the edge of his perch is assumed to have staggered a short distance toward the edge before dropping over",
    }, {
      "name" = "wfcLowPrecariousKnockdown",
      "value" = true,
      "comment" = "the rule also applies to a precariously balanced character not at a high elevation: he is in danger of being knocked off his feet by a large amount of damage, and will certainly fall down - as would anyone in a more stable position - if rendered unconscious",
    }, {
      "name" = "wfcWaterSleepSuffocation",
      "value" = true,
      "comment" = "a character who is knee-deep in water and gets hit by a sleep spell will keel over; beginning the following round he must make Constitution Checks as though holding his breath underwater and out of air, and dies if he does not regain consciousness or is not rescued before failing one",
    }, {
      "name" = "wfcLooseSoilFaceDownCheck",
      "value" = true,
      "comment" = "a character who falls unconscious in loose soil - including sand - or snow must make a Dexterity Check with a -2 modifier to the die roll; failure indicates he has landed face down and must then begin Constitution Checks, dying of suffocation if not revived or at least rolled over before failing one",
    }, {
      "name" = "wfcKnockdownDexCheck",
      "value" = true,
      "comment" = "whenever a character is knocked off his feet and does not lose consciousness, he must make a Dexterity Check",
    }, {
      "name" = "wfcKnockdownFullRoundFail",
      "value" = true,
      "comment" = "a failed check means he must take a full round to stand and resume a fighting posture",
    }, {
      "name" = "wfcRegainHalfRoundAction",
      "value" = true,
      "comment" = "a character who gets to his feet quickly may be able to make an attack or cast a spell during the last half of the round, if other conditions permit",
    }, {
      "name" = "wfcWaterKneeNoDexBonus",
      "value" = true,
      "comment" = "a character in combat while standing in water at least up to his knees but not higher than his waist does not enjoy any armor class benefit due to dexterity",
    }, {
      "name" = "wfcAttackerSamePenalty",
      "value" = true,
      "comment" = "any opponent attempting to hit a character who is immersed or partially immersed in water does so at the same penalty to its attack rolls - even if the opponent is not immersed - reflecting that a smaller portion of the character's body is vulnerable to a weapon blow",
    }, {
      "name" = "wfcAquaticNativeExempt",
      "value" = true,
      "comment" = "these penalties do not apply to a creature native to an aquatic environment, assuming it can strike freely above the water or below the surface",
    }, {
      "name" = "wfcSwimProficiencyRelief",
      "value" = true,
      "comment" = "for a character with proficiency in swimming, the chest and over-chest penalties are reduced by one-half - to -1 and -2 respectively - and the waist-deep penalty does not apply",
    }, {
      "name" = "wfcTotalDarkBonusNegated",
      "value" = true,
      "comment" = "the vision-based attack bonus is fully negated in total darkness",
    }, {
      "name" = "wfcBonusCutExamples",
      "value" = true,
      "comment" = "the vision-based bonus category includes a thief's backstabbing skill, a ranger's special prowess against giant-class creatures, or the special severing property of a sword of sharpness commanded not to shed any light",
    }, {
      "name" = "wfcTotalDarkWildSwing",
      "value" = true,
      "comment" = "when meleeing in total darkness, if the attacker's modified to-hit roll is 0 or less he has accidentally struck another object or creature, if some other target exists within the wild-swing radius",
    }, {
      "name" = "wfcWildSwingRandomTarget",
      "value" = true,
      "comment" = "if more than one unintended target is in range, the Dungeon Master randomly determines which object, creature or character has been hit - including other members of the attacker's party",
    }, {
      "name" = "wfcWildSwingObjectSave",
      "value" = true,
      "comment" = "an object hit by a wild swing must save versus crushing blow to avoid being broken or destroyed; a creature or character takes the appropriate damage after the poor-visibility damage penalty is taken into account",
    }, {
      "name" = "wfcNaturalDarkWildElseMiss",
      "value" = true,
      "comment" = "if the natural-darkness wild-swing roll fails, the attack hits nothing within range",
    }, {
      "name" = "wfcMoonlightIlluminationExempt",
      "value" = true,
      "comment" = "if the illumination is at least equivalent to moonlight, neither the climbing nor the precarious-position darkness penalty applies",
    }, {
      "name" = "wfcSpecialVisionExempt",
      "value" = true,
      "comment" = "a character using infravision or ultravision, and able to benefit from the ability, is not subject to any of the poor-visibility penalties",
    }, {
      "name" = "wfcIlluminationRangeExempt",
      "value" = true,
      "comment" = "any character within the range of natural or magical illumination is not penalized",
    }, {
      "name" = "wfcWeatherCumulative",
      "value" = true,
      "comment" = "all adjustments for inclement weather - high wind and precipitation - are cumulative with any other modifiers that apply; even the most accomplished fighter will have a tough time hitting anything in the dark of night during a howling rainstorm",
    }, {
      "name" = "wfcMountLargerNoBonus",
      "value" = true,
      "comment" = "the mounted character receives no bonus if the opponent is larger",
    }, {
      "name" = "wfcExactHitStrikesMount",
      "value" = true,
      "comment" = "if the foot character's to-hit roll - including all other modifiers - is exactly the number he would have needed to hit his foe, the attack hits the mount instead of the rider",
    }, {
      "name" = "wfcChooseStrikeMount",
      "value" = true,
      "comment" = "a character on foot can choose to strike against the mount instead of the rider, which can often be a good tactic",
    }, {
      "name" = "wfcFlyingMountLowEngagement",
      "value" = true,
      "comment" = "a character on a flying mount can engage in melee with a nearby airborne opponent, or with a foe on the ground if the mount is flying low enough to make it possible",
    }, {
      "name" = "wfcAirborneNoElevationAdjustment",
      "value" = true,
      "comment" = "if two antagonists are both airborne, the combat adjustments for relative elevation usually do not apply - the combatants are assumed to be constantly jockeying for position, neither voluntarily remaining in a vulnerable position",
    }, {
      "name" = "wfcBracedDefense",
      "value" = true,
      "comment" = "a character on the ground may defend against an attack from above by remaining in one spot and bracing himself for the onslaught",
    }, {
      "name" = "wfcBraceForfeitsDexBonus",
      "value" = true,
      "comment" = "the braced defender forfeits any armor class bonus due to dexterity",
    }, {
      "name" = "wfcPullUpBreaksOff",
      "value" = true,
      "comment" = "an airborne opponent, noticing the braced tactic, can choose to pull up and break off the attack, in which case neither combatant will score a hit",
    }, {
      "name" = "wfcHoverNeededForMulti",
      "value" = true,
      "comment" = "a character on a flying mount must be able to hover in close proximity to a land-based opponent to benefit from multiple attacks per round",
    }, {
      "name" = "wfcVeerPreventsFollowups",
      "value" = true,
      "comment" = "an attacker who closes to take one swing and then veers away to avoid being hit in return will not be able to change course in time to get a second or third attack",
    }, {
