      "value" = true,
      "comment" = "most flying creatures have very poor maneuverability when used as mounts, and are not capable of repeated abrupt changes of direction or other precise maneuvers",
    }, {
      "name" = "wfcMissileNeedsRidingProf",
      "value" = true,
      "comment" = "only a character with proficiency in riding his mount can successfully use a missile weapon from the back of a moving mount, whether airborne or land-based",
    }, {
      "name" = "wfcMissileNeedsBothHands",
      "value" = true,
      "comment" = "even if the weapon does not actually require two hands, the character must be able to ride with both hands free - one of the abilities included in the land-based and airborne riding proficiencies",
    }, {
      "name" = "wfcMissileLongbowExcluded",
      "value" = true,
      "comment" = "any missile weapon except a longbow can be used from the back of a moving mount",
    }, {
      "name" = "wfcMissileHeavyCrossbowExcluded",
      "value" = true,
      "comment" = "a heavy crossbow also cannot be used from the back of a moving mount",
    }, {
      "name" = "wfcRofOneStepReduction",
