    }, {
      "name" = "wfcSpeedPenaltiesCumulative",
      "value" = true,
      "comment" = "the mount-speed penalties are in addition to all others - range, visibility, etc. - that may apply",
    }, {
      "name" = "wfcComplexManeuversBlock",
      "value" = true,
      "comment" = "missile fire is impossible while the mount is performing complex maneuvers",
    }, {
      "name" = "wfcTerrainMayBlock",
      "value" = true,
      "comment" = "at the Dungeon Master's discretion, missile combat from the back of a moving land-based mount may be impossible in terrain conditions where the rider is forced to use at least one hand to hold onto his mount",
    }, {
      "name" = "wfcFlyingShortAsMedium",
      "value" = true,
      "comment" = "as noted in the Dungeon Master's Guide on page 53, on a flying mount short range is treated as medium range for to-hit modifiers unless the mount is hovering",
    }, {
      "name" = "wfcFlyingMediumAsLong",
      "value" = true,
      "comment" = "medium range from a flying mount is considered long range for to-hit modifiers unless hovering",
    }, {
      "name" = "wfcHoverNoExtraToHit",
      "value" = true,
      "comment" = "a hovering rider suffers no additional to-hit penalties but still must abide by the reduction in rate of fire",
    }, {
      "name" = "wfcDismountBothDirections",
      "value" = true,
      "comment" = "a mounted character should always anticipate the possibility that his opponent may attack his mount or otherwise cause him to fall, and should be alert for the opportunity to separate a mounted opponent from its steed; an unseated opponent is at worst on equal terms with a character on the ground, at best disadvantaged if the character is still in the saddle",
    }, {
      "name" = "wfcLandMountDeathFall",
      "value" = true,
      "comment" = "if a land-based mount is killed while a character is riding it, the character instantly falls to the ground",
    }, {
      "name" = "wfcRidingCheckLandsOnFeet",
      "value" = true,
      "comment" = "a character with proficiency in riding the mount will land on his feet if he makes a successful Proficiency Check, and will be able to perform normally during the remainder of the round in which he falls",
    }, {
      "name" = "wfcTumbleRecoveryTwoRounds",
      "value" = true,
      "comment" = "the tumbling rider must spend the remainder of the current round and all of the following round getting back to his feet and regaining his bearings",
    }, {
      "name" = "wfcFlyingMountHalfHpChecks",
      "value" = true,
      "comment" = "if a flying mount takes damage that brings it to less than half of its total hit points, the rider must immediately make a check to see if he falls, with further checks required in every round until the mount is brought to a landing or regains enough hit points to put it out of danger",
    }, {
      "name" = "wfcClericCanKeepMountFlying",
      "value" = true,
      "comment" = "a cleric equipped with several cure wounds spells could keep his mount flying for quite a while, as long as the creature is among those that can be affected by such magic",
    }, {
      "name" = "wfcFlyingMountDeathPlummet",
      "value" = true,
      "comment" = "if a flying mount is killed while a character is aboard, the creature will plummet to the ground and most likely also carry the rider to his death, especially if the rider is securely strapped onto the mount (the close-to-the-ground tail rides to the next round)",
    }, {
      "name" = "wfcLeapFromMount",
      "value" = true,
      "comment" = "the Dungeon Master may allow a character with proficiency in riding the mount to leap from its back and land safely on the ground - usually only when the mount is hovering, though the DM could grant the chance under other conditions with a die-roll modifier on the Proficiency Check",
    }, {
      "name" = "wfcUnseatProfCheckRetains",
      "value" = true,
      "comment" = "if the unseat victim has riding proficiency and makes a successful Proficiency Check, he retains his seat; otherwise - if the check fails or the rider is not proficient - he falls to the ground and takes 1d3 points of damage",
    }, {
      "name" = "wfcPullDownGrapple",
      "value" = true,
      "comment" = "a character - mounted or on foot - can attempt to unseat a mounted opponent by pulling him down: moving adjacent, diving toward his foe, and making a successful to-hit roll as if attacking with his bare hands to grapple",
    }, {
      "name" = "wfcGrappleVictimProfCheck",
      "value" = true,
      "comment" = "the grappled mounted opponent is allowed a Proficiency Check, if applicable, to see if he remains on the mount; success means he has not been unseated and the attacker is clinging to him or the mount",
    }, {
      "name" = "wfcGrappleFailAttackerFalls",
      "value" = true,
      "comment" = "if the original grapple attempt fails, the attacker falls to the ground and suffers 1d6 points of damage",
    }, {
      "name" = "wfcClingToHitEachRound",
      "value" = true,
      "comment" = "an attacker remaining clinging to a mounted opponent must make successful to-hit rolls in each subsequent round to remain in that position; failure on any roll means he has fallen with the usual effects",
    }, {
      "name" = "wfcRiderCheckOrBothFall",
      "value" = true,
      "comment" = "if the clinging attacker's to-hit roll in any round succeeds, the rider must make a Proficiency Check to prevent falling - and taking the attacker along with him",
    }, {
      "name" = "wfcRiderMayAttackGrappler",
      "value" = true,
      "comment" = "at the Dungeon Master's discretion a rider may be able to use his weapon to attack a grappling opponent, but if such an attack is possible it is made with a -2 penalty to hit",
    } },
  "switches" = {},
