  "examples" = { {
      "note" = "the climbing penalties: the cliff face costs -2 while the severe slope costs -1, with the elevation adjustments +2/-2 on the cliff and +1/-1 on the slope",
      "expr" = "m['wfcCliffAtkPenalty']() != m['wfcCliffSavePenalty']() or m['wfcSevereSlopeAtkPenalty']() >= m['wfcCliffAtkPenalty']() or m['wfcElevHighBonusCliff']() != m['wfcElevLowPenaltyCliff']() or m['wfcElevHighBonusSevere']() != m['wfcElevLowPenaltySevere']() or m['wfcElevHighBonusSevere']() >= m['wfcElevHighBonusCliff']()",
    }, {
      "note" = "the shield strapped to the back gives one step for a buckler or small shield and two for a larger shield, and the moderate-slope elevation option uses the severe +1/-1 pair",
      "expr" = "m['wfcShieldBackSmallSteps']() + 1 != m['wfcShieldBackLargeSteps']() or m['wfcElevHighBonusSevere']() != 1",
    }, {
      "note" = "the damage checks: the severe-slope damage check gains +10 percent while the big-damage check loses 10 percent, both from the Climbing Rating",
      "expr" = "m['wfcDamageCheckSevereBonus']() != m['wfcBigDamageCheckPenalty']() or m['wfcBigDamageCheckPenalty']() != 10",
    }, {
      "note" = "the balance modifiers: mud -4, wide ledge -2, the nine-foot edge -18 built from -2 per foot, with 19 and 20 the auto-fail rolls",
      "expr" = "m['wfcDexModMud']() != 2 * m['wfcDexModWideLedge']() or m['wfcNineFtEdgeMod']() != 9 * m['wfcEdgePerFootMod']() or m['wfcAutoFailRollLow']() + 1 != m['wfcAutoFailRollHigh']() or m['wfcNotPrecariousFt']() != 10",
    }, {
      "note" = "the knockdown rules: five segments to regain feet on a success, the loose-soil check at -2 and the slippery check at +4",
      "expr" = "m['wfcRegainFeetSegments']() != 5 or m['wfcSlipperyDexMod']() != 4 or m['wfcLooseSoilDexMod']() != 2",
    }, {
      "note" = "the water penalties ascend 1, 2 and 4 by depth with the damage floor at 1 point",
      "expr" = "m['wfcWaterKneePenalty']() >= m['wfcWaterChestPenalty']() or m['wfcWaterChestPenalty']() >= m['wfcWaterOverChestPenalty']() or m['wfcWaterDmgMin']() != 1",
    }, {
      "note" = "the visibility penalties ascend 1, 3 and 4 from moonlight to total darkness, with the bonus cut one-quarter in moonlight and one-half in natural darkness",
      "expr" = "m['wfcMoonlightPenalty']() >= m['wfcNaturalDarkPenalty']() or m['wfcNaturalDarkPenalty']() >= m['wfcTotalDarkPenalty']() or m['wfcNaturalDarkBonusCutNum']() * 2 != m['wfcMoonlightBonusCutNum']()",
    }, {
      "note" = "the darkness adjustments double from natural to total: the climbing cut 5 to 10 percent and the precarious modifier +1 to +2, with the wild-swing radius at twice weapon length and the natural-dark wild swing at 50 percent",
      "expr" = "m['wfcDarkClimbCut']() * 2 != m['wfcTotalDarkClimbCut']() or m['wfcDarkPrecariousDexMod']() * 2 != m['wfcTotalDarkPrecariousDexMod']() or m['wfcWildSwingRadiusMult']() != 2 or m['wfcNaturalDarkWildPct']() != 50",
    }, {
      "note" = "the mount melee numbers: +1 same size, -1 smaller, -1 on foot, airborne +1 and swooping +2, the brace +4 with a 3-foot weapon",
      "expr" = "m['wfcMountSameSizeBonus']() != m['wfcMountSmallerPenalty']() or m['wfcFootVsMountedPenalty']() != 1 or m['wfcSwoopChargeBonus']() != 2 * m['wfcAirborneVsGroundBonus']() or m['wfcBraceBonus']() != 4 or m['wfcBraceWeaponMinFt']() != 3",
    }, {
      "note" = "the rate-of-fire scale runs from 6/1 down to the 1/1 floor, and the javelin specialist drops one step from 5/2 to 2/1",
      "expr" = "m['wfcRofBestPerRound']() != 6 or m['wfcRofFloorNum']() != 1 or m['wfcRofFloorDen']() != 1 or m['wfcJavelinNormalNum']() != 5 or m['wfcJavelinNormalDen']() != 2 or m['wfcJavelinMountedNum']() != 2 or m['wfcJavelinMountedDen']() != 1",
